@using sv_683ddb1e13ac4070b2756b3a8c069866.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <h3>Step 1: Patient Information</h3>

    <div class="mb-3">
        <label class="form-label">Patient Name</label>
        <InputText @bind-Value="Model.PatientName" class="form-control" />
        <ValidationMessage For="() => Model.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <InputText @bind-Value="Model.Email" class="form-control" />
        <ValidationMessage For="() => Model.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone</label>
        <InputText @bind-Value="Model.Phone" class="form-control" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Insurance Provider</label>
        <InputSelect @bind-Value="Model.InsuranceProvider" class="form-control">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => Model.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @if (showStep2)
    {
        <h3>Step 2: Appointment Details</h3>

        <div class="mb-3">
            <label class="form-label">Preferred Doctor</label>
            <InputSelect @bind-Value="Model.Doctor" class="form-control" @bind:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.Doctor" />
        </div>

        <div class="mb-3">
            <label class="form-label">Date</label>
            <InputDate @bind-Value="Model.AppointmentDate" class="form-control" @bind:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="() => Model.AppointmentDate" />
        </div>

        <div class="mb-3">
            <label class="form-label">Time Slot</label>
            <InputSelect @bind-Value="Model.TimeSlot" class="form-control">
                <option value="">-- Select --</option>
                @foreach (var slot in availableSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.TimeSlot" />
        </div>

        <div class="mb-3">
            <label class="form-label">Reason for Visit</label>
            <InputTextArea @bind-Value="Model.Reason" class="form-control" rows="3" />
            <ValidationMessage For="() => Model.Reason" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability" disabled="@isChecking">
            @(isChecking ? "Checking..." : "Check Availability")
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">
            Book Appointment
        </button>
    }
</EditForm>

@if (booked)
{
    <div class="alert alert-success mt-3">Appointment booked successfully!</div>
}

@code {
    private EditContext editContext = default!;
    private CustomValidator? customValidator;
    private BookAppointmentModel Model = new();
    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool booked;
    private List<string> doctors = new();
    private List<string> availableSlots = new();

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private bool ValidateStep1()
    {
        var results = new List<ValidationResult>();
        var context = new ValidationContext(Model);
        // Validate only step 1 fields
        var step1Fields = new[] { nameof(Model.PatientName), nameof(Model.Email), nameof(Model.Phone), nameof(Model.InsuranceProvider) };

        bool isValid = true;
        foreach (var field in step1Fields)
        {
            var prop = typeof(BookAppointmentModel).GetProperty(field)!;
            var value = prop.GetValue(Model);
            var fieldContext = new ValidationContext(Model) { MemberName = field };
            var fieldResults = new List<ValidationResult>();
            if (!Validator.TryValidateProperty(value, fieldContext, fieldResults))
            {
                isValid = false;
            }
        }

        // Trigger EditContext validation to show messages
        editContext.Validate();
        return isValid;
    }

    private void ProceedToStep2()
    {
        if (ValidateStep1())
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityConfirmed = false;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
            Model.TimeSlot = null;
        }
    }

    private async Task CheckAvailability()
    {
        customValidator!.ClearErrors();
        availabilityConfirmed = false;

        // Validate all fields first
        if (!editContext.Validate())
        {
            return;
        }

        // Check future date
        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            customValidator.DisplayErrors(new Dictionary<string, List<string>>
            {
                [nameof(Model.AppointmentDate)] = ["Date must be in the future."]
            });
            return;
        }

        isChecking = true;

        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email ?? "", Model.InsuranceProvider, Model.Doctor ?? "", Model.TimeSlot ?? "");

            if (errors.Count > 0)
            {
                customValidator.DisplayErrors(errors);
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityConfirmed && editContext.Validate())
        {
            booked = true;
        }
    }
}

